//! `geom-num`'s Verus crate (chapter 28.7 of the kernel architecture; pieces G36, G37 and G38):
//! the twins of the code that ships, with Verus's specifications and proofs added, for `verus` to
//! verify. Cargo never builds it.
//!
//! - `wide`: the wide integers' arithmetic (`src/wide.rs`), written by hand.
//! - `model`: the model of `geom_num::grid`'s types the predicate twins verify against.
//! - `orient2d`, `orient3d`, `incircle` and `insphere`: the predicates' exact paths
//!   (`src/generated/`), generated by `geom-gen` into `generated/`.
//!
//! `geom-gen`'s `tests/verus_twin.rs` holds every twin to the shipped code token for token.
//! Verify: `verus --crate-type=lib projects/engines/geometry/crates/geom-num/verus/lib.rs`, with the
//! Verus release `kernel-dev.yml` pins; its `verus` job does this on every pull request.

#![feature(proc_macro_hygiene)]

pub mod model;
pub mod wide;

#[path = "generated/orient2d.rs"]
pub mod orient2d;
#[path = "generated/orient3d.rs"]
pub mod orient3d;
#[path = "generated/incircle.rs"]
pub mod incircle;
#[path = "generated/insphere.rs"]
pub mod insphere;
